CREATE TABLE t (id Uint64 NOT NULL, a Utf8, PRIMARY KEY (id), INDEX t_a GLOBAL ON (a));
CREATE TABLE t (id Uint64 NOT NULL, a Utf8, PRIMARY KEY (id));
ALTER TABLE t DROP COLUMN a;
